export type IconName = keyof typeof ICONS;

// Inline SVG icon, sized in px and coloured by currentColor
export function Icon({
  name,
  size = 14,
  className,
}: {
  name: IconName;
  size?: number;
  className?: string;
}) {
  const { viewBox, d } = ICONS[name];
  return (
    <svg
      aria-hidden
      viewBox={viewBox}
      width={size}
      height={size}
      className={className}
      fill="currentColor"
    >
      <path d={d} />
    </svg>
  );
}
